-- =====================================================================
-- 011: katalog misji 4 specjalizacji — pełne opisy z briefu
-- Po 012. Następnie uruchom 013 (brak deadlinu + ewentualny refresh opisów).
-- =====================================================================

update public.mission_definitions set is_active = false
where code in ('critic_three_pins','critic_best_dish','rescuer_foodshare','chef_signature','connector_open_table','explorer_three_recommended','romantic_tasting');

-- duration_hours zostaje w schemacie (wymagane > 0), ale 013 wyłącza expires_at.
on conflict (code) do update set name = excluded.name, description = excluded.description, specialization_code = excluded.specialization_code, reward_xp = excluded.reward_xp, is_active = true, confirmation_method = excluded.confirmation_method, duration_hours = excluded.duration_hours, cooldown_hours = 0;

on conflict (code) do update set name = excluded.name, description = excluded.description, specialization_code = excluded.specialization_code, reward_xp = excluded.reward_xp, is_active = true, safety_rules = excluded.safety_rules, duration_hours = excluded.duration_hours, cooldown_hours = 0;

on conflict (code) do update set name = excluded.name, description = excluded.description, specialization_code = excluded.specialization_code, reward_xp = excluded.reward_xp, is_active = true, safety_rules = excluded.safety_rules, duration_hours = excluded.duration_hours, cooldown_hours = 0;

on conflict (code) do update set name = excluded.name, description = excluded.description, specialization_code = excluded.specialization_code, reward_xp = excluded.reward_xp, is_active = true, safety_rules = excluded.safety_rules, duration_hours = excluded.duration_hours, cooldown_hours = 0;

update public.mission_definitions set is_active = true where code = 'starter_hello';
update public.mission_definitions set duration_hours = 876000, cooldown_hours = 0 where is_active and specialization_code in ('detective','host','alchemist','guardian');
