insert into public.mission_definitions (code, name, description, category, specialization_code, participation, difficulty, confirmation_method, duration_hours, reward_xp, repeat_reward_xp, repeat_limit, cooldown_hours, steps, safety_rules) values
('det_ghost_venue', 'Lokal Widmo', 'Znajdź knajpę, której nie ma jeszcze na mapie Yummeet. Dodaj pinezkę z nazwą, lokalizacją, kategorią kuchni i podstawowymi informacjami.', 'restaurant', 'detective', 'solo', 1, 'self', 876000, 60, 15, 0, 0, '[]'::jsonb, null),
('det_unknown_cuisine', 'Operacja: Nieznana Kuchnia', 'Znajdź lokal serwujący wskazany rodzaj kuchni, np. gruzińską, koreańską, wietnamską lub etiopską. Jeśli nie ma go na mapie, dodaj pinezkę.', 'restaurant', 'detective', 'solo', 2, 'self', 876000, 70, 15, 0, 0, '[]'::jsonb, null),
('det_two_tens', 'Obiad za Dwie Dychy', 'Znajdź lokal, w którym można zjeść obiad za maksymalnie 20 zł. Podaj przykładowe danie, cenę i źródło informacji. Zapisz go w kategorii Tanie.', 'restaurant', 'detective', 'solo', 2, 'self', 876000, 70, 15, 0, 0, '[]'::jsonb, null),
('det_off_radar', 'Lokal Poza Radarem', 'Odkryj miejsce, które łatwo przeoczyć: ukryte na podwórku, w bocznej uliczce, na piętrze albo poza głównym szlakiem gastronomicznym.', 'restaurant', 'detective', 'solo', 2, 'self', 876000, 80, 20, 0, 0, '[]'::jsonb, null),
('det_blank_spot', 'Biała Plama na Mapie', 'Wybierz obszar mapy z małą liczbą pinezek i znajdź tam nowy lokal.', 'travel', 'detective', 'solo', 2, 'self', 876000, 80, 20, 0, 0, '[]'::jsonb, null),
('det_tgtg', 'Misja: Ocalony Posiłek', 'Znajdź lokal oferujący paczki przez Too Good To Go lub podobną usługę. Dodaj pinezkę albo zapisz w pinie kategorię Paczki TGTG.', 'food_rescue', 'detective', 'solo', 2, 'self', 876000, 70, 15, 0, 0, '[]'::jsonb, null),
('det_happy_hour', 'Godzina Słabości Cenowej', 'Znajdź knajpę, w której o określonej porze można zjeść taniej, np. podczas happy hours, lunchu dnia lub wieczornej wyprzedaży. Zapisz w tej restauracji kategorię Happy-Hour.', 'restaurant', 'detective', 'solo', 2, 'self', 876000, 70, 15, 0, 0, '[]'::jsonb, null),
('det_full_belly', 'Król Pełnego Brzucha', 'Znajdź miejsce, w którym można dostać sycący posiłek w ustalonym budżecie, np. do 25 lub 30 zł. Podaj konkretną propozycję z menu. Zapisz pin z kategorią Duże porcje.', 'restaurant', 'detective', 'solo', 2, 'self', 876000, 70, 15, 0, 0, '[]'::jsonb, null),
('det_green_trail', 'Zielony Trop', 'Znajdź lokal z ciekawą ofertą wegetariańską lub wegańską. Nie wystarczy, że w menu jest jedna sałatka — celem jest znalezienie miejsca z sensownym wyborem dań. Zapisz pina z kategorią wegetariańskie lub wegańskie.', 'restaurant', 'detective', 'solo', 2, 'self', 876000, 70, 15, 0, 0, '[]'::jsonb, null),
('det_no_traps', 'Menu Bez Pułapek', 'Znajdź lokal z oznaczonymi opcjami bezglutenowymi lub inną wskazaną kategorią żywieniową. Zapisz wyłącznie to, co potwierdza menu lub obsługa. Zapisz pin z kategorią np. bezglutenowe.', 'restaurant', 'detective', 'solo', 2, 'self', 876000, 70, 15, 0, 0, '[]'::jsonb, null),
('det_after_hours', 'Głód po Godzinach', 'Znajdź lokal, w którym można zjeść po 22:00. Zweryfikuj godziny otwarcia i rodzaj dostępnego jedzenia. Zapisz pin z kategorią nocne.', 'restaurant', 'detective', 'solo', 2, 'self', 876000, 70, 15, 0, 0, '[]'::jsonb, null),
('det_group_table', 'Stół dla Ekipy', 'Znajdź miejsce odpowiednie dla grupy, np. z dużymi stolikami, daniami do dzielenia się lub rozsądnymi cenami przy większym zamówieniu. Zapisz pin z kategorią grupowe.', 'social', 'detective', 'solo', 2, 'self', 876000, 70, 15, 0, 0, '[]'::jsonb, null),
('det_breakfast', 'Śniadaniowy Alarm', 'Znajdź lokal, w którym można zjeść śniadanie przed określoną godziną, najlepiej w cenie mieszczącej się w wyznaczonym budżecie. Zapisz pin z kategorią śniadania.', 'restaurant', 'detective', 'solo', 1, 'self', 876000, 60, 15, 0, 0, '[]'::jsonb, null),
('det_receipt', 'Operacja: Aktualny Paragon', 'Uzupełnij brakujące ceny, kategorie albo opis menu w pinie, w którym nie ma tych opisów, albo są niewystarczające.', 'review', 'detective', 'solo', 2, 'self', 876000, 80, 10, 0, 0, '[]'::jsonb, null),
('det_field_report', 'Raport z Miejsca Zdarzenia', 'Odwiedź lokal zapisany na mapie i oceń go według kwestionariusza Yummeet. Dodaj krótką opinię o jedzeniu i wskaż, komu polecasz to miejsce.', 'review', 'detective', 'solo', 2, 'self', 876000, 80, 20, 0, 0, '[]'::jsonb, null),
('det_best_dessert', 'Najlepszy deser', 'Dodaj pin lokalu, w którym można zjeść twoim zdaniem najlepszy deser lub słodycze. Opisz nazwę i cenę deseru, który polecasz.', 'restaurant', 'detective', 'solo', 1, 'self', 876000, 60, 15, 0, 0, '[]'::jsonb, null),
('det_baker', 'Pan Piekarz', 'Dodaj pin z kategorią Piekarnia.', 'restaurant', 'detective', 'solo', 1, 'self', 876000, 50, 10, 0, 0, '[]'::jsonb, null)
insert into public.mission_definitions (code, name, description, category, specialization_code, participation, difficulty, confirmation_method, duration_hours, reward_xp, repeat_reward_xp, repeat_limit, cooldown_hours, steps, safety_rules) values
('host_empty_table', 'Pusty Stół Czeka', 'Zorganizuj swoje pierwsze otwarte spotkanie. Wybierz miejsce, termin i temat, który może zachęcić innych do przyjścia. Nie musi być wyszukany — ważne, żeby powstała realna okazja do poznania ludzi.', 'social', 'host', 'group', 1, 'self', 876000, 80, 20, 0, 0, '[]'::jsonb, 'Zadbaj o bezpieczeństwo. Użytkownicy powinni móc zgłaszać niewłaściwe zachowania podczas spotkań, a organizator powinien jasno określać miejsce i warunki spotkania. Nie należy publikować prywatnych danych uczestników bez ich zgody.'),
('host_singles', 'Dla singli', 'Zorganizuj kameralne spotkanie dla osób, które są singlami i chciałyby się lepiej poznać.', 'dating', 'host', 'group', 2, 'self', 876000, 90, 20, 0, 0, '[]'::jsonb, null),
('host_picnic', 'Piknik Bez Biletu Wstępu', 'Zorganizuj plenerowe spotkanie, na które każdy może przynieść własny prowiant. Ustal dostępne miejsce, godzinę i plan na wypadek złej pogody.', 'social', 'host', 'group', 2, 'self', 876000, 80, 20, 0, 0, '[]'::jsonb, null),
('host_skills_share', 'Każdy Umie Coś, Czego Ty Nie Umiesz', 'Zorganizuj spotkanie, na którym każdy uczestnik dzieli się jedną umiejętnością, przydatną wskazówką albo doświadczeniem. Mogą to być języki, praca, podróże, majsterkowanie, gotowanie czy obsługa przydatnych narzędzi.', 'social', 'host', 'group', 2, 'self', 876000, 80, 20, 0, 0, '[]'::jsonb, null),
('host_problem_idea', 'Mam Problem, Mam Pomysł', 'Zorganizuj spotkanie, podczas którego uczestnicy przedstawiają niewielki problem, z którym się mierzą, a pozostali wspólnie szukają rozwiązań. Mogą to być kwestie organizacji czasu, nauki, szukania pracy czy rozwijania projektu.', 'social', 'host', 'group', 2, 'self', 876000, 80, 20, 0, 0, '[]'::jsonb, null),
('host_idea_market', 'Giełda Pomysłów', 'Wybierz jeden temat — np. pomysły na dodatkowy zarobek, lokalną inicjatywę, mały biznes lub ciekawy projekt — i zbierz osoby, które chcą wymienić się pomysłami. Każdy powinien wyjść przynajmniej z jedną inspiracją do dalszego sprawdzenia.', 'social', 'host', 'group', 2, 'self', 876000, 80, 20, 0, 0, '[]'::jsonb, null),
('host_babel', 'Wieża Babel', 'Zorganizuj spotkanie dla osób, które chcą ćwiczyć języki obce. Uczestnicy mogą rozmawiać w parach, zmieniać partnerów i pomagać sobie w nauce.', 'social', 'host', 'group', 2, 'self', 876000, 80, 20, 0, 0, '[]'::jsonb, null),
('host_other_view', 'Świat Widziany Inaczej', 'Wybierz temat, na który ludzie mogą mieć odmienne zdania, i zaproś uczestników do spokojnej dyskusji. Celem nie jest wygranie sporu, lecz zrozumienie, dlaczego inni myślą inaczej.', 'social', 'host', 'group', 2, 'self', 876000, 80, 20, 0, 0, '[]'::jsonb, null),
('host_one_book', 'Jedna Książka, Wiele Światów', 'Zorganizuj spotkanie wokół książki, filmu, podcastu lub artykułu. Każdy może opowiedzieć, co go zaciekawiło, z czym się nie zgadzał albo co zmieniło jego spojrzenie na temat.', 'social', 'host', 'group', 2, 'self', 876000, 80, 20, 0, 0, '[]'::jsonb, null),
('host_other_side', 'Po Drugiej Stronie Zawodu', 'Zaproś osoby z różnych branż do rozmowy o tym, jak naprawdę wygląda ich praca, czego się nauczyły i co zaskoczyło je w ich zawodzie. Nie chodzi o rekrutację ani sprzedaż usług.', 'social', 'host', 'group', 2, 'self', 876000, 80, 20, 0, 0, '[]'::jsonb, null),
('host_small_change', 'Mała Zmiana, Wielka Sprawa', 'Zorganizuj spotkanie osób, które chcą zrobić coś pożytecznego w swojej okolicy. Wybierzcie realny cel, np. pomoc lokalnej inicjatywie, zbiórkę potrzebnych rzeczy albo uporządkowanie wspólnej przestrzeni, i ustalcie pierwszy krok.', 'volunteer', 'host', 'group', 3, 'self', 876000, 100, 25, 0, 0, '[]'::jsonb, null),
('host_no_waste', 'Nic Się Nie Marnuje', 'Zorganizuj spotkanie wymiany książek, roślin, gier, sprawnych przedmiotów lub innych rzeczy, które mogą przydać się komuś innemu.', 'social', 'host', 'group', 2, 'self', 876000, 80, 20, 0, 0, '[]'::jsonb, null),
('host_from_scratch', 'Projekt z Niczego', 'Zbierz grupę, która w trakcie jednego spotkania wymyśli i zaplanuje mały wspólny projekt — np. klub wymiany umiejętności, lokalną mapę ciekawych miejsc albo cykl spotkań tematycznych.', 'social', 'host', 'group', 3, 'self', 876000, 90, 20, 0, 0, '[]'::jsonb, null),
('host_chess', 'Gambit Towarzyski', 'Zorganizuj otwarte spotkanie szachowe. Zaproś zarówno początkujących, jak i zaawansowanych graczy; można rozegrać szybkie partie, nauczyć się podstaw albo po prostu poćwiczyć.', 'social', 'host', 'group', 2, 'self', 876000, 80, 20, 0, 0, '[]'::jsonb, null),
('host_boardgames', 'Plansza Łączy Ludzi', 'Zorganizuj wieczór gier planszowych lub karcianych. Wybierz gry, do których łatwo dołączyć, nawet jeśli uczestnicy nie znają się wcześniej.', 'social', 'host', 'group', 2, 'self', 876000, 80, 20, 0, 0, '[]'::jsonb, null),
('host_quiz', 'Turniej Wiedzy Bezużytecznej', 'Zorganizuj quiz z nietypowych ciekawostek, popkultury, geografii, historii itp. Temat dowolny.', 'social', 'host', 'group', 2, 'self', 876000, 80, 20, 0, 0, '[]'::jsonb, null),
('host_curious', 'Klub Ludzi Ciekawych', 'Zorganizuj spotkanie, podczas którego uczestnicy pokażą innym swoje hobby: fotografię, rysowanie, origami, pisanie, modelarstwo lub coś zupełnie nieoczywistego.', 'social', 'host', 'group', 2, 'self', 876000, 80, 20, 0, 0, '[]'::jsonb, null),
('host_three_steps', 'Trzy Kroki Naprzód', 'Zorganizuj spotkanie, podczas którego każdy chętny przedstawia jeden cel, nad którym pracuje, oraz najbliższy mały krok. Pozostali mogą zaproponować pomysł, kontakt lub pomoc — bez oceniania i nieproszonych wykładów.', 'social', 'host', 'group', 2, 'self', 876000, 80, 20, 0, 0, '[]'::jsonb, null),
('host_elder_wolf', 'Wiedza Starszego Wilka', 'Zorganizuj spotkanie, na którym osoby z większym doświadczeniem w wybranej dziedzinie dzielą się nim z początkującymi. Tematem może być nauka, praca, podróże, hobby albo rozwijanie własnego projektu.', 'social', 'host', 'group', 2, 'self', 876000, 90, 20, 0, 0, '[]'::jsonb, null),
('host_map_ops', 'Mapa Możliwości', 'Zorganizuj spotkanie poświęcone odkrywaniu możliwości, o których uczestnicy mogli wcześniej nie wiedzieć: ciekawych wydarzeń, bezpłatnych kursów, lokalnych inicjatyw, klubów zainteresowań czy sposobów rozwijania umiejętności.', 'social', 'host', 'group', 2, 'self', 876000, 80, 20, 0, 0, '[]'::jsonb, null),
('host_tasting', 'Wielka Degustacja', 'Zorganizuj spotkanie, podczas którego uczestnicy spróbują różnych pizz lub innych dań do dzielenia się. Każdy sam decyduje, co zamawia i ile wydaje. Korzyść: pretekst do rozmowy i poznawania nowych smaków.', 'social', 'host', 'group', 2, 'self', 876000, 80, 20, 0, 0, '[]'::jsonb, null),
('host_sugar', 'Rada Miłośników Cukru', 'Zorganizuj spotkanie poświęcone deserom, ciastom, lodom lub innym słodkościom. Możecie odwiedzić cukiernię albo urządzić własną degustację.', 'social', 'host', 'group', 2, 'self', 876000, 80, 20, 0, 0, '[]'::jsonb, null)
insert into public.mission_definitions (code, name, description, category, specialization_code, participation, difficulty, confirmation_method, duration_hours, reward_xp, repeat_reward_xp, repeat_limit, cooldown_hours, steps, safety_rules) values
('alc_four_ingredients', 'Cztery Składniki, Zero Wymówek', 'Wybierz dwie różne potrawy i zrób z nich fuzję. Wykorzystaj elementy jednego dania w drugim, albo połącz je tak by stworzyć coś nowego. Podziel się zdjęciem, przepisem i krótkim opisem wykonania.', 'cooking', 'alchemist', 'solo', 2, 'self', 876000, 80, 20, 0, 0, '[]'::jsonb, null),
('alc_last_zloty', 'Bitwa o Ostatnią Złotówkę', 'Przygotuj pełnowartościowy posiłek tak by koszt produkcji był jak najtańszy, a ugotowana potrawa była smacznym i pełnowartościowym posiłkiem. Podaj koszt składników i liczbę uzyskanych porcji.', 'cooking', 'alchemist', 'solo', 2, 'self', 876000, 80, 20, 0, 0, '[]'::jsonb, null),
('alc_vs_restaurant', 'Restauracja kontra Twoja Kuchnia', 'Wybierz danie znane z dobrej restauracji i przygotuj własną wersję w domu. Pokaż rezultat, koszt porcji i opisz, co udało się odtworzyć, a co zrobiłbyś inaczej następnym razem.', 'cooking', 'alchemist', 'solo', 3, 'self', 876000, 100, 25, 0, 0, '[]'::jsonb, null),
('alc_no_passport', 'Podróż Bez Paszportu', 'Wylosuj kuchnię kraju, którego rzadko używasz w swojej kuchni. Przygotuj charakterystyczne danie i opublikuj przepis wraz z informacją, skąd pochodzi inspiracja. Korzyść: odkrywanie nowych smaków i kultur.', 'cooking', 'alchemist', 'solo', 2, 'self', 876000, 80, 20, 0, 0, '[]'::jsonb, null),
('alc_level_up', 'Awans Alchemika', 'Wybierz jedną technikę, której jeszcze dobrze nie opanowałeś — np. przygotowanie sosu, wyrabianie ciasta, karmelizację cebuli lub flambirowanie. Przećwicz ją i opublikuj rezultat wraz z wnioskami.', 'cooking', 'alchemist', 'solo', 2, 'self', 876000, 70, 15, 0, 0, '[]'::jsonb, null),
('alc_first_swap', 'Pierwsza Zamiana Obiadów', 'Jeśli ugotowałeś czegoś wystarczająco dużo, zaproponuj wymianę z innym Yummiterem. Ustalcie wcześniej rodzaj posiłków, liczbę porcji, miejsce i termin przekazania.', 'food_exchange', 'alchemist', 'pair', 2, 'peer', 876000, 100, 25, 0, 0, '[]'::jsonb, 'Aplikacja nie pośredniczy w płatnościach. Alergeny obowiązkowe.'),
('alc_lunch_for_lunch', 'Obiad za Obiad', 'Umów się z drugim Yummiterem na gotowanie na żądanie. Ty przygotowujesz danie dla niego, a on przygotowuje coś dla Ciebie. Określcie wcześniej budżet, temat kulinarny i danie które ugotujecie dla siebie na wymianę.', 'food_exchange', 'alchemist', 'pair', 3, 'peer', 876000, 110, 30, 0, 0, '[]'::jsonb, 'Aplikacja nie pośredniczy w płatnościach.'),
('alc_specialty_swap', 'Specjalność za Specjalność', 'Znajdź osobę, która specjalizuje się w czymś innym niż Ty. Wymieńcie się swoimi popisowymi potrawami — np. pierogami za chleb na zakwasie albo curry za domowe wypieki.', 'food_exchange', 'alchemist', 'pair', 3, 'peer', 876000, 110, 30, 0, 0, '[]'::jsonb, null),
('alc_pan_secret', 'Sekret Mistrza Patelni', 'Opublikuj własny sprawdzony trik, który rzeczywiście poprawia efekt gotowania — np. sposób uzyskania chrupiących ziemniaków, lepszego sosu lub bardziej puszystego omletu. Pokaż rezultat i wyjaśnij, dlaczego metoda działa.', 'cooking', 'alchemist', 'solo', 1, 'self', 876000, 60, 15, 0, 0, '[]'::jsonb, null),
('alc_apprentice', 'Ucznia Przyjmę', 'Zorganizuj krótkie spotkanie lub wspólne gotowanie, podczas którego nauczysz drugiego Yummitera jednej konkretnej umiejętności kulinarnej. Nie musi to być skomplikowana rzecz — ważne, żeby druga osoba mogła samodzielnie powtórzyć technikę.', 'cooking', 'alchemist', 'pair', 3, 'peer', 876000, 100, 25, 0, 0, '[]'::jsonb, null),
('alc_recipe_story', 'Przepis z Historią', 'Opublikuj swój sprawdzony przepis z proporcjami, czasem przygotowania, kosztem i jedną wskazówką, której nie ma w typowym przepisie. Może to być rodzinne danie albo własna modyfikacja.', 'cooking', 'alchemist', 'solo', 2, 'self', 876000, 80, 20, 0, 0, '[]'::jsonb, null),
('alc_signature', 'Mój Kulinarny Znak Firmowy', 'Wybierz potrawę, w której czujesz się najlepiej. Przygotuj jej opis, zdjęcie, orientacyjny koszt składników i liczbę porcji. Dodaj ją do swojego profilu jako specjalność i wystaw na zamianę obiadów jeśli twój poziom umiejętności kulinarnych jest na co najmniej 3 poziomie.', 'cooking', 'alchemist', 'solo', 2, 'self', 876000, 80, 20, 0, 0, '[]'::jsonb, null),
('alc_first_order', 'Pierwsze Zamówienie', 'Udostępnij ofertę przygotowania jednej konkretnej potrawy na zamówienie. Określ liczbę porcji, termin, cenę lub zasady pokrycia kosztów i sposób odbioru. Przyjmij pierwsze zlecenie, jeśli możesz je bezpiecznie zrealizować.', 'cooking', 'alchemist', 'pair', 3, 'peer', 876000, 120, 30, 0, 0, '[]'::jsonb, 'Wymaga oświadczeń sanitarno-prawnych przy włączeniu gotowania odpłatnego. Aplikacja nie jest sprzedawcą.'),
('alc_cover_ingredients', 'Gotuję, Ty Pokrywasz Składniki', 'Udostępnij ofertę przygotowania jednej konkretnej potrawy w zamian za opłacenie składników. Odbiorca pokrywa uzgodniony koszt produktów, a gotowa potrawa jest dzielona po równo. Przed rozpoczęciem ustalcie budżet, liczbę porcji i sposób rozliczenia.', 'cooking', 'alchemist', 'pair', 3, 'peer', 876000, 110, 30, 0, 0, '[]'::jsonb, 'Bez pól finansowych w aplikacji.'),
('alc_menu_wish', 'Menu na Życzenie', 'Dodaj do swojego profilu opis trzech potraw, które możesz wykonać na zamówienie. Przy każdej podaj cenę, wielkość porcji, możliwe modyfikacje i czas potrzebny na przygotowanie.', 'cooking', 'alchemist', 'solo', 2, 'self', 876000, 70, 15, 0, 0, '[]'::jsonb, null),
('alc_duet', 'Duet przy Desce', 'Znajdź drugiego Yummitera i przygotujcie wspólnie danie wymagające podziału pracy. Możecie wybrać kuchnię, której żadne z was nie zna dobrze, i wspólnie opracować przepis.', 'cooking', 'alchemist', 'pair', 3, 'peer', 876000, 100, 25, 0, 0, '[]'::jsonb, null),
('alc_tasters_table', 'Stół Degustatorów', 'Zorganizuj niewielkie spotkanie, na którym kilka osób przynosi własne potrawy do spróbowania. Uczestnicy dzielą się konstruktywną opinią i mogą wymienić się przepisami.', 'social', 'alchemist', 'group', 3, 'self', 876000, 100, 25, 0, 0, '[]'::jsonb, null),
('alc_three_versions', 'Jedno Danie, Trzy Wersje', 'Rzuć wyzwanie dwóm innym Yummiterom: przygotujcie własne wersje tej samej potrawy. Porównajcie składniki, techniki i rezultaty, podzielcie się tipami na jak najlepsze jej wykonanie.', 'cooking', 'alchemist', 'group', 3, 'self', 876000, 110, 30, 0, 0, '[]'::jsonb, null),
('alc_bigger_cause', 'Garnek Dla Większej Sprawy', 'Zorganizuj gotowanie na potrzeby uzgodnionej inicjatywy społecznej, np. wydarzenia sąsiedzkiego lub zbiórki. Wcześniej ustal odbiorców, finansowanie składników i sposób bezpiecznego przekazania jedzenia. Korzyść: wykorzystanie umiejętności kulinarnych w działaniu na rzecz innych.', 'volunteer', 'alchemist', 'group', 3, 'self', 876000, 120, 30, 0, 0, '[]'::jsonb, 'Bezpieczeństwo żywności priorytetem.')
insert into public.mission_definitions (code, name, description, category, specialization_code, participation, difficulty, confirmation_method, duration_hours, reward_xp, repeat_reward_xp, repeat_limit, cooldown_hours, steps, safety_rules) values
('gua_bakery_bell', 'Ostatni Dzwonek Piekarni', 'Znajdź piekarnię, która pod koniec dnia przecenia lub przekazuje niesprzedane pieczywo. Dodaj lokal do mapy z kategoriami Piekarnia i Przeceny, albo zaktualizuj jego ofertę, podając godzinę odbioru i zasady rezerwacji.', 'food_rescue', 'guardian', 'solo', 2, 'self', 876000, 70, 15, 0, 0, '[]'::jsonb, null),
('gua_saved_pastry', 'Misja: Ocalony Wypiek', 'Znajdź aktualną ofertę nadwyżek z cukierni lub kawiarni. Dodaj ją na mapę z pinem Cukiernia, Przeceny, jeśli jeszcze jej nie ma, albo zaktualizuj jej ofertę, podając godzinę odbioru i zasady rezerwacji, jeśli już jest.', 'food_rescue', 'guardian', 'solo', 2, 'self', 876000, 70, 15, 0, 0, '[]'::jsonb, null),
('gua_last_chance', 'Paczka Ostatniej Szansy', 'Odbierz paczkę z Too Good To Go lub podobnej usługi. Zapisz jej rodzaj, orientacyjną zawartość, koszt i sposób wykorzystania produktów. Dodaj pina z informacją o lokalu jeśli go nie ma, lub aktualizuj jego pin o kategorię przeceny.', 'food_rescue', 'guardian', 'solo', 2, 'self', 876000, 80, 20, 0, 0, '[]'::jsonb, null),
('gua_last_portion', 'Ostatnia Porcja Przed Zamknięciem', 'Znajdź lokal, który przekazuje niesprzedane, bezpieczne posiłki. Ustal z personelem zasady odbioru, sposób pakowania i czas, w którym jedzenie można odebrać i opisz je w pinie. Dodaj lub aktualizuj pin tego lokalu na mapie z kategorią Jadłodzielnia.', 'food_rescue', 'guardian', 'solo', 3, 'self', 876000, 90, 20, 0, 0, '[]'::jsonb, null),
('gua_open_pantry', 'Spiżarnia Otwartych Drzwi', 'Opublikuj jedzenie, którego już nie wykorzystasz, ale które nadal nadaje się do bezpiecznego przekazania. Podaj ilość, skład, alergeny, czas odbioru i warunki przechowywania.', 'food_rescue', 'guardian', 'solo', 2, 'self', 876000, 80, 20, 0, 0, '[]'::jsonb, 'Nie publikuj żywności niepewnej lub po terminie „należy spożyć do”.'),
('gua_good_taste_courier', 'Kurier Dobrego Smaku', 'Odbierz zgłoszone jedzenie od jednego Yummitera i przekaż je do jadłodzielni.', 'food_rescue', 'guardian', 'pair', 3, 'peer', 876000, 100, 25, 0, 0, '[]'::jsonb, null),
('gua_second_life_map', 'Mapa Drugiego Życia', 'Znajdź jadłodzielnię, sprawdź jej lokalizację, godziny dostępności i zasady przyjmowania produktów. Dodaj jej pin do mapy.', 'food_rescue', 'guardian', 'solo', 2, 'self', 876000, 80, 20, 0, 0, '[]'::jsonb, null),
('gua_course_fridge', 'Kurs na Jadłodzielnię', 'Przetransportuj produkty spożywcze do jadłodzielni. Udokumentuj przekazanie bez fotografowania przypadkowych osób ani ujawniania danych odbiorców.', 'food_rescue', 'guardian', 'solo', 2, 'self', 876000, 90, 20, 0, 0, '[]'::jsonb, null),
('gua_still_alive', 'Punkt, Który Nadal Żyje', 'Zweryfikuj, jakie produkty są obecnie w jadłodzielni, i aktualizuj pin z jej dzisiejszym stanem. Opisz co jest dostępne, do kiedy (jeśli to możliwe) i wrzuć zdjęcie. Jeśli w lodówce nie ma nic, to nie publikuj aktualizacji.', 'food_rescue', 'guardian', 'solo', 2, 'self', 876000, 70, 15, 0, 0, '[]'::jsonb, null),
('gua_red_labels', 'Czerwone Etykiety', 'Znajdź sklep, który przecenia produkty z krótkim terminem przydatności. Dodaj informację o rodzaju przecen i typowych porach przecen. Pokaż właścicielowi aplikację, zachęć do jej pobrania i aktualizowania informacji o pojawiających się przecenach.', 'food_rescue', 'guardian', 'solo', 2, 'self', 876000, 70, 15, 0, 0, '[]'::jsonb, null),
('gua_greengrocer', 'Sekret Warzywniaka', 'Odkryj warzywniak, który oferuje tańsze produkty do szybkiego wykorzystania. Opisz, co można tam znaleźć i w jakich godzinach mogą pojawić się przeceny. Pokaż właścicielowi aplikację, zachęć do jej pobrania i aktualizowania informacji o pojawiających się przecenach.', 'food_rescue', 'guardian', 'solo', 2, 'self', 876000, 70, 15, 0, 0, '[]'::jsonb, null),
('gua_restaurant_ally', 'Sojusz z restauracją', 'Nawiąż kontakt z lokalem gastronomicznym, który chce ograniczyć marnowanie. Pokaż mu aplikację, zachęć do jej pobrania i aktualizowania informacji o pojawiających się daniach do odebrania za darmo lub na sporej przecenie.', 'food_rescue', 'guardian', 'solo', 3, 'self', 876000, 100, 25, 0, 0, '[]'::jsonb, null)
